import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, Send, Bot, User, Mic, MicOff } from 'lucide-react';
import './ChatPage.css';

const ChatPage = ({ userLocation }) => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Auto-scroll to bottom when new messages arrive
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    // Welcome message
    addMessage('bot', 'Hello! I\'m your farming assistant. I can help you with crop advice, pest control, weather information, and more. What would you like to know about?');
  }, []);

  const addMessage = (sender, text) => {
    const newMessage = {
      id: Date.now(),
      sender,
      text,
      timestamp: new Date().toLocaleTimeString()
    };
    setMessages(prev => [...prev, newMessage]);
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage = inputMessage.trim();
    setInputMessage('');
    setIsLoading(true);

    // Add user message
    addMessage('user', userMessage);

    try {
      // Call the backend streaming API
      const response = await fetch('http://0.0.0.0:8000/farm-assistant', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ query: userMessage }),
      });

      if (!response.ok) {
        throw new Error('Failed to get response from server');
      }

      // Handle streaming response
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let aiResponse = '';

      // Add initial bot message
      const botMessageId = Date.now();
      const initialBotMessage = {
        id: botMessageId,
        sender: 'bot',
        text: '',
        timestamp: new Date().toLocaleTimeString()
      };
      setMessages(prev => [...prev, initialBotMessage]);

      // Stream the response
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        aiResponse += chunk;

        // Update the bot message with streaming text
        setMessages(prev => 
          prev.map(msg => 
            msg.id === botMessageId 
              ? { ...msg, text: aiResponse }
              : msg
          )
        );
      }

    } catch (error) {
      console.error('Error calling farm assistant API:', error);
      addMessage('bot', 'Sorry, I\'m having trouble connecting to my knowledge base right now. Please try again in a moment.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const toggleRecording = () => {
    setIsRecording(!isRecording);
    // In a real app, this would integrate with speech-to-text API
    if (!isRecording) {
      // Start recording
      console.log('Recording started...');
    } else {
      // Stop recording
      console.log('Recording stopped...');
      // Simulate speech-to-text result
      setTimeout(() => {
        setInputMessage('How to grow tomatoes?');
      }, 1000);
    }
  };

  const quickQuestions = [
    'How to grow wheat?',
    'Tomato pest control',
    'Best time to plant rice',
    'Soil testing methods',
    'Irrigation tips'
  ];

  return (
    <div className="chat-page page-transition">
      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            <MessageCircle className="page-icon" />
            AI Farming Assistant
          </h1>
          <p className="page-subtitle">Get instant advice on crops, pests, weather, and farming techniques</p>
        </div>

        <div className="chat-container">
          <div className="chat-messages">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`message ${message.sender === 'user' ? 'user-message' : 'bot-message'}`}
              >
                <div className="message-avatar">
                  {message.sender === 'user' ? (
                    <User className="avatar-icon" />
                  ) : (
                    <Bot className="avatar-icon" />
                  )}
                </div>
                <div className="message-content">
                  <div className="message-text">{message.text}</div>
                  <div className="message-time">{message.timestamp}</div>
                </div>
              </div>
            ))}

            {isLoading && (
              <div className="message bot-message">
                <div className="message-avatar">
                  <Bot className="avatar-icon" />
                </div>
                <div className="message-content">
                  <div className="typing-indicator">
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                    <div className="typing-dot"></div>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          <div className="quick-questions">
            <h3>Quick Questions</h3>
            <div className="question-chips">
              {quickQuestions.map((question, index) => (
                <button
                  key={index}
                  className="question-chip"
                  onClick={() => setInputMessage(question)}
                >
                  {question}
                </button>
              ))}
            </div>
          </div>

          <div className="chat-input-container">
            <div className="chat-input-wrapper">
              <textarea
                className="chat-input"
                placeholder="Ask me anything about farming..."
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                onKeyPress={handleKeyPress}
                rows="1"
                disabled={isLoading}
              />
              <div className="input-actions">
                <button
                  className={`voice-btn ${isRecording ? 'recording' : ''}`}
                  onClick={toggleRecording}
                  disabled={isLoading}
                >
                  {isRecording ? <MicOff /> : <Mic />}
                </button>
                <button
                  className="send-btn"
                  onClick={handleSendMessage}
                  disabled={!inputMessage.trim() || isLoading}
                >
                  <Send />
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="chat-info">
          <div className="info-card">
            <h3>What I can help with:</h3>
            <ul>
              <li>🌾 Crop selection and growing tips</li>
              <li>🐛 Pest and disease identification</li>
              <li>🌤️ Weather and seasonal advice</li>
              <li>🌱 Soil health and fertilization</li>
              <li>💧 Irrigation and water management</li>
              <li>📅 Harvest timing and techniques</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPage;
